+import { describe, it, expect, beforeEach } from 'vitest'
+import { GithubApi, InvalidIssueUrlError } from '../index.js'
+
+beforeEach(() => {
+  // ensure env reset
+  delete process.env.GITHUB_HOSTS
+})
+
+describe('parseIssueUrl', () => {
+  const g = new GithubApi()
+
+  const accept = (url: string, host = 'github.com') => {
+    const parsed = g.parseIssueUrl(url)
+    expect(parsed.host).toBe(host)
+    expect(parsed.owner).toBe('o')
+    expect(parsed.repo).toBe('r')
+    expect(parsed.issueNumber).toBe(12)
+  }
+
+  it('accepts basic github url', () => {
+    accept('https://github.com/o/r/issues/12')
+  })
+
+  it('accepts trailing slash', () => {
+    accept('https://github.com/o/r/issues/12/')
+  })
+
+  it('accepts query strings and fragments', () => {
+    accept('https://github.com/o/r/issues/12?foo=1#bar')
+  })
+
+  it('accepts www.github.com', () => {
+    accept('https://www.github.com/o/r/issues/12', 'www.github.com')
+  })
+
+  it('accepts enterprise hosts listed in GITHUB_HOSTS (case-insensitive)', () => {
+    process.env.GITHUB_HOSTS = 'GHE.example.com'
+    const g2 = new GithubApi()
+    const parsed = g2.parseIssueUrl('https://ghe.example.com/o/r/issues/12')
+    expect(parsed.host).toBe('ghe.example.com')
+    expect(parsed.owner).toBe('o')
+    expect(parsed.repo).toBe('r')
+    expect(parsed.issueNumber).toBe(12)
+  })
+
+  it('rejects pull request URLs', () => {
+    expect(() => g.parseIssueUrl('https://github.com/o/r/pull/12')).toThrow(InvalidIssueUrlError)
+  })
+
+  it('rejects http URLs', () => {
+    expect(() => g.parseIssueUrl('http://github.com/o/r/issues/12')).toThrow(InvalidIssueUrlError)
+  })
+
+  it('rejects non-numeric issue numbers', () => {
+    expect(() => g.parseIssueUrl('https://github.com/o/r/issues/abc')).toThrow(InvalidIssueUrlError)
+  })
+
+  it('rejects zero issue number', () => {
+    expect(() => g.parseIssueUrl('https://github.com/o/r/issues/0')).toThrow(InvalidIssueUrlError)
+  })
+
+  it('rejects unknown hosts', () => {
+    expect(() => g.parseIssueUrl('https://notgithub.com/o/r/issues/12')).toThrow(InvalidIssueUrlError)
+  })
+
+  it('rejects invalid owner/repo names', () => {
+    expect(() => g.parseIssueUrl('https://github.com/!nvalid/repo/issues/12')).toThrow(InvalidIssueUrlError)
+    expect(() => g.parseIssueUrl('https://github.com/owner/has space/issues/12')).toThrow(InvalidIssueUrlError)
+  })
+})
