+        } catch (err) {
+            throw new InvalidIssueUrlError("Invalid URL")
         }
+        if (u.protocol !== "https:") throw new InvalidIssueUrlError("Only https URLs are allowed")
+
+        const host = u.hostname.toLowerCase()
+        const envHosts = (process.env.GITHUB_HOSTS ?? "").split(",").map(h=>h.trim().toLowerCase()).filter(Boolean)
+        const allowed = new Set(["github.com","www.github.com", ...envHosts])
+        if (!allowed.has(host)) throw new InvalidIssueUrlError(`Unknown host: ${host}`)
+
+        // path: /owner/repo/issues/123 ... allow trailing slash, query, fragment
+        const m = u.pathname.match(/^\/([^/]+)\/([^/]+)\/issues\/(\d+)(?:\/?)$/)
+        if (!m) throw new InvalidIssueUrlError("Not an issue URL")
+        const [, owner = "", repo = "", numStr = "0"] = m
