+        const ownerRepoRe = /^[A-Za-z0-9_.-]+$/
+        if (!ownerRepoRe.test(owner) || !ownerRepoRe.test(repo)) throw new InvalidIssueUrlError("Invalid owner or repo name")
+
+        const issueNumber = parseInt(numStr, 10)
+        if (!Number.isFinite(issueNumber) || issueNumber <= 0) throw new InvalidIssueUrlError("Invalid issue number")
+
+        return { host, owner, repo, issueNumber }
     }

